function conditionOk(choice, progress) {
    const c = choice?.condition;
    if (c == null)
        return true;
    if (typeof c !== 'string')
        return false;
    if (c.startsWith('unvisited:'))
        return !progress.visitedNodeIds.includes(c.slice(10));
    if (c.startsWith('visited:'))
        return progress.visitedNodeIds.includes(c.slice(8));
    if (c === 'flag:shipDepartureVerified')
        return Boolean(progress.flags?.shipCoursePlotted && progress.flags?.shipBuraFound);
    if (c === 'flag:shipThwheekCombatStarted')
        return progress.currentNodeId === 'thwheek-orbit' && progress.flags?.shipThwheekInterceptionRequired === true && !progress.flags?.shipThwheekCombatStarted;
    if (c.startsWith('flag:'))
        return Boolean(progress.flags?.[c.slice(5)]);
    if (c.startsWith('!flag:'))
        return !Boolean(progress.flags?.[c.slice(6)]);
    if (c.startsWith('encounter-resolved:'))
        return (progress.encounterHistory || []).some(x => x.encounterId === c.slice(19) && x.outcome === 'adversaries_defeated');
    return false;
}
