function conditionOk(choice, progress) {
    const c = choice?.condition;
    if (!c)
        return true;
    if (typeof c !== 'string')
        return false;
    if (c.startsWith('unvisited:'))
        return !progress.visitedNodeIds.includes(c.slice(10));
    if (c.startsWith('visited:'))
        return progress.visitedNodeIds.includes(c.slice(8));
    if (c.startsWith('flag:'))
        return Boolean(progress.flags?.[c.slice(5)]);
    if (c.startsWith('check-success:'))
        return (progress.checkHistory || []).some(x => x.nodeId === c.slice(14) && x.success === true);
    if (c.startsWith('check-failure:'))
        return (progress.checkHistory || []).some(x => x.nodeId === c.slice(14) && x.success === false);
    if (c.startsWith('encounter-resolved:'))
        return (progress.encounterHistory || []).some(x => x.encounterId === c.slice(19) && ['adversaries_defeated', 'negotiated'].includes(x.outcome));
    return false; // Unknown conditions must never unlock a scene or reward.
}
