        chase.rounds = Number(chase.rounds || 0) + 1;
        chase.status = chase.lead >= 2 ? (nodeId === 'hot-pursuit' ? 'vantagem' : 'rastro_firme') : chase.lead <= -2 ? (nodeId === 'hot-pursuit' ? 'comprometida' : 'rastro_perdido') : 'active';
        chase.last = { success, delta, netAdvantage, triumph, despair };
