            credits += 25;
        if (netAdvantage <= -2)
            credits -= 25;
        credits += triumph * 100 - despair * 100;
        sabacc.rounds = Number(sabacc.rounds || 0) + 1;
        sabacc.creditsDelta = Number(sabacc.creditsDelta || 0) + credits;
